import fs from "node:fs";
import crypto from "node:crypto";
import { AES_IV, AES_KEY, ENCRYPTED_MAGIC, HEADER_SIZE } from "./constants.js";

export function isEncrypted(buf) {
  return buf.length >= 8 && buf.subarray(0, 8).equals(ENCRYPTED_MAGIC);
}

/**
 * Decrypt a DUIX gjdigits blob (AES-128-CBC, no padding).
 * Layout: magic(8) + originalSize(u64le) + reserved(16) + ciphertext.
 */
export function decryptBuffer(buf) {
  if (!isEncrypted(buf)) return Buffer.from(buf);
  const originalSize = Number(buf.readBigUInt64LE(8));
  const encrypted = buf.subarray(HEADER_SIZE);
  const aligned = encrypted.length - (encrypted.length % 16);
  if (aligned <= 0) return Buffer.alloc(0);
  const decipher = crypto.createDecipheriv(
    "aes-128-cbc",
    Buffer.from(AES_KEY, "ascii"),
    Buffer.from(AES_IV, "ascii"),
  );
  decipher.setAutoPadding(false);
  const out = Buffer.concat([decipher.update(encrypted.subarray(0, aligned)), decipher.final()]);
  if (originalSize > 0 && originalSize < out.length) return out.subarray(0, originalSize);
  return out;
}

export function decryptFile(filePath) {
  return decryptBuffer(fs.readFileSync(filePath));
}

export function decryptJson(filePath) {
  const raw = decryptFile(filePath);
  const text = raw.toString("utf8").replace(/\0+$/g, "").trim();
  return JSON.parse(text);
}
